#include <stdbool.h>
#include <stdio.h>
#include "structures/bst.h"

static bool parent_links_valid(const Node *node, const Node *parent) {
    if (node == NULL) return true;
    return node->parent == parent &&
           parent_links_valid(node->left, node) &&
           parent_links_valid(node->right, node);
}

static void print_tree(const char *name, Node *root) {
    printf("%s balanced=%s height=%d parents=%s inorder=",
           name,
           bst_is_almost_balanced(root) ? "yes" : "no",
           bst_height(root),
           parent_links_valid(root, NULL) ? "yes" : "no");
    bst_print_inorder(root);
    printf("\n");
}

int main(void) {
    const int seven[] = {1, 2, 3, 4, 5, 6, 7};
    const int six[] = {-3, 0, 4, 8, 12, 15};

    Node *built7 = bst_build_balanced(seven, 7);
    print_tree("build7", built7);
    bst_free(built7);

    Node *built6 = bst_build_balanced(six, 6);
    print_tree("build6", built6);
    bst_free(built6);

    Node *skewed = NULL;
    for (int value = 1; value <= 8; value++) {
        skewed = bst_insert(skewed, value);
    }
    Node *rebalanced = bst_rebalance(skewed);
    print_tree("rebalance8", rebalanced);
    bst_free(rebalanced);

    Node *empty = bst_build_balanced(NULL, 0);
    print_tree("empty", empty);
    bst_free(empty);
    return 0;
}

